import{i as e,r as t,s as n,t as r}from"./app-5wwWw4mj.js";var i=JSON.parse(`{"path":"/rareboxproblem/","title":"以下是RareBox或Rare调试系软件常见的问题。","lang":"zh-CN","frontmatter":{"permalink":"/rareboxproblem/","description":"Rare软件常见问题解答"},"git":{},"filePathRelative":"rareboxproblem.md"}`),a={name:`rareboxproblem.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="以下是rarebox或rare调试系软件常见的问题。" tabindex="-1"><a class="header-anchor" href="#以下是rarebox或rare调试系软件常见的问题。"><span>以下是RareBox或Rare调试系软件常见的问题。</span></a></h1><p>方便起见，以下简称<strong>RareBox或Rare调试系软件</strong>为<strong>Rare软件</strong>。</p><h2 id="如何打开adb调试和wlan调试功能" tabindex="-1"><a class="header-anchor" href="#如何打开adb调试和wlan调试功能"><span>如何打开ADB调试和WLAN调试功能？</span></a></h2><h3 id="_1-首先在手表上启用开发者选项" tabindex="-1"><a class="header-anchor" href="#_1-首先在手表上启用开发者选项"><span>1.首先在手表上启用开发者选项</span></a></h3><p>您必须先启用开发者选项，才能在手表上进行调试。您只需执行此操作一次。开发者选项将保持启用状态，直到您将其停用。 打开手表的设置。依次点按系统 &gt; 关于。滚动到版本号并点按版本号七次。将出现一个对话框，确认您现在已处于开发者模式。</p><h3 id="_2-启用-wlan-调试" tabindex="-1"><a class="header-anchor" href="#_2-启用-wlan-调试"><span>2.启用 WLAN 调试</span></a></h3><p>打开手表的设置。</p><p>依次点按开发者选项 &gt; adb 调试。</p><p>然后点击 通过 WLAN 调试。</p><h3 id="_3-补充说明" tabindex="-1"><a class="header-anchor" href="#_3-补充说明"><span>3.补充说明</span></a></h3><p>近期很多相同某品牌手表用户无法使用RareClean软件，请左滑界面切换到Shell模式运行！</p><h2 id="提示no-route-to-host怎么办" tabindex="-1"><a class="header-anchor" href="#提示no-route-to-host怎么办"><span>提示No Route To Host怎么办</span></a></h2><p>大概率你输错ip地址了，请检查输入。</p><p>否则一般可能是路由器打开了 AP 隔离功能，由于路由器太多品牌了，请自行搜索如何关闭该项功能。</p><p>如果实在不会搞，您也可以创建无线热点并连接手表。</p><p><strong>另外，部分学校的网络做了校园网认证和/或AP隔离，这样的网络无法进行WLAN调试，靠个人无法解决（除非你是神级人物，可以随便发号施令改造学校）！请自寻靠谱的网络解决！</strong></p><h2 id="如何安装apks-多重apk-文件" tabindex="-1"><a class="header-anchor" href="#如何安装apks-多重apk-文件"><span>如何安装apks（多重apk）文件</span></a></h2><p>重命名.apks为.zip，解压缩，然后把里面的apk依次安装就行了。</p><h2 id="远程连接时一直连接不上-手表总是掉线" tabindex="-1"><a class="header-anchor" href="#远程连接时一直连接不上-手表总是掉线"><span>远程连接时一直连接不上/手表总是掉线</span></a></h2><p>简而言之，请在使用Rare软件时，<strong>关闭手表的省电模式、手机和手表的蓝牙功能、启用eSIM功能的手表请暂时关闭eSIM功能（比如开飞行模式后打开WLAN（WLAN一定要开且连上））</strong>，这样就行了。可能有些表就是刁钻，那我也没办法了（摊手）。</p><h2 id="android表怎么连接" tabindex="-1"><a class="header-anchor" href="#android表怎么连接"><span>Android表怎么连接</span></a></h2><p>用电脑连接手表，执行以下adb命令</p><p>对于Windows系统的命令提示符等请使用</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">adb tcpip <span class="token number">5555</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>对于Windows系统的PowerShell、类Unix/Linux系统等请使用</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">./adb tcpip <span class="token number">5555</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>然后就可以在RareBox里面通过<code>&lt;ip地址&gt;:5555</code>连接了。</p><p>注意：这种方法每次重启后都要操作。如果想一劳永逸请Root手表，配合Rikka大佬的WADB工具食用。</p><h2 id="本文版权" tabindex="-1"><a class="header-anchor" href="#本文版权"><span>本文版权</span></a></h2><p>未经作者明确授权，禁止一切形式摘编或转载！</p>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};